  private baseState = State.Text
  /** For special parsing behavior inside of script and style tags. */
  public inRCDATA = false
  /** For disabling RCDATA tags handling */
  public inXML = false
  /** For disabling interpolation parsing in v-pre */
  public inVPre = false
  /** Record newline positions for fast line / column calculation */
  private newlines: number[] = []

  private readonly entityDecoder?: EntityDecoder

  public mode: ParseMode = ParseMode.BASE
  public get inSFCRoot(): boolean {
    return this.mode === ParseMode.SFC && this.stack.length === 0
  }

  constructor(
    private readonly stack: ElementNode[],
    private readonly cbs: Callbacks,
  ) {
    if (!__BROWSER__) {
      this.entityDecoder = new EntityDecoder(htmlDecodeTree, (cp, consumed) =>
        this.emitCodePoint(cp, consumed),
      )
    }
  }

  public reset(): void {
    this.state = State.Text
    this.mode = ParseMode.BASE
----
    let column = index + 1
    for (let i = this.newlines.length - 1; i >= 0; i--) {
      const newlineIndex = this.newlines[i]
      if (index > newlineIndex) {
        line = i + 2
        column = index - newlineIndex
        break
      }
    }
    return {
      column,
      line,
      offset: index,
    }
  }

  private peek() {
    return this.buffer.charCodeAt(this.index + 1)
  }

  private stateText(c: number): void {
    if (c === CharCodes.Lt) {
      if (this.index > this.sectionStart) {
        this.cbs.ontext(this.sectionStart, this.index)
      }
      this.state = State.BeforeTagName
      this.sectionStart = this.index
    } else if (!__BROWSER__ && c === CharCodes.Amp) {
      this.startEntity()
    } else if (!this.inVPre && c === this.delimiterOpen[0]) {
      this.state = State.InterpolationOpen
      this.delimiterIndex = 0
      this.stateInterpolationOpen(c)
    }
  }

  public delimiterOpen: Uint8Array = defaultDelimitersOpen
  public delimiterClose: Uint8Array = defaultDelimitersClose
  private delimiterIndex = -1

  private stateInterpolationOpen(c: number): void {
    if (c === this.delimiterOpen[this.delimiterIndex]) {
      if (this.delimiterIndex === this.delimiterOpen.length - 1) {
        const start = this.index + 1 - this.delimiterOpen.length
        if (start > this.sectionStart) {
          this.cbs.ontext(this.sectionStart, start)
        }
        this.state = State.Interpolation
        this.sectionStart = start
      } else {
        this.delimiterIndex++
      }
    } else if (this.inRCDATA) {
      this.state = State.InRCDATA
      this.stateInRCDATA(c)
    } else {
      this.state = State.Text
      this.stateText(c)
    }
  }

  private stateInterpolation(c: number): void {
    if (c === this.delimiterClose[0]) {
      this.state = State.InterpolationClose
      this.delimiterIndex = 0
      this.stateInterpolationClose(c)
    }
  }

  private stateInterpolationClose(c: number) {
    if (c === this.delimiterClose[this.delimiterIndex]) {
      if (this.delimiterIndex === this.delimiterClose.length - 1) {
        this.cbs.oninterpolation(this.sectionStart, this.index + 1)
        if (this.inRCDATA) {
          this.state = State.InRCDATA
        } else {
          this.state = State.Text
        }
        this.sectionStart = this.index + 1
      } else {
        this.delimiterIndex++
      }
    } else {
      this.state = State.Interpolation
      this.stateInterpolation(c)
    }
  }

  public currentSequence: Uint8Array = undefined!
  private sequenceIndex = 0
  private stateSpecialStartSequence(c: number): void {
    const isEnd = this.sequenceIndex === this.currentSequence.length
    const isMatch = isEnd
      ? // If we are at the end of the sequence, make sure the tag name has ended
        isEndOfTagSection(c)
      : // Otherwise, do a case-insensitive comparison
        (c | 0x20) === this.currentSequence[this.sequenceIndex]

    if (!isMatch) {
      this.inRCDATA = false
    } else if (!isEnd) {
      this.sequenceIndex++
      return
    }

    this.sequenceIndex = 0
    this.state = State.InTagName
    this.stateInTagName(c)
  }

  /** Look for an end tag. For <title> and <textarea>, also decode entities. */
  private stateInRCDATA(c: number): void {
    const sequence = this.currentSequence
    const sequenceLength = sequence.length
    const isTitleSequence = sequence === Sequences.TitleEnd
    const isTextareaSequence = sequence === Sequences.TextareaEnd
    const inSfcRoot = this.inSFCRoot
    const delimiterOpen = this.delimiterOpen
    const delimiterOpenLength = delimiterOpen.length

    let firstCode = 0
    let secondCode = 0
    if (sequenceLength > 0) {
      firstCode = sequence[0]
    }
    if (sequenceLength > 1) {
      secondCode = sequence[1]
    }

    let rcdataTagName = ''
    const canReadTagName = sequenceLength > 2
    const firstIsLt = firstCode === CharCodes.Lt
    const secondIsSlash = secondCode === CharCodes.Slash
    if (canReadTagName) {
      if (firstIsLt) {
        if (secondIsSlash) {
          for (let i = 2; i < sequenceLength; i++) {
            const code = sequence[i]
            const foldedCode = code | 0x20
            if (
              foldedCode >= CharCodes.LowerA &&
              foldedCode <= CharCodes.LowerZ
            ) {
              const letter = String.fromCharCode(foldedCode)
              rcdataTagName += letter
            } else {
              break
            }
          }
        }
      }
    }

    const titleIsNative = isHTMLTag('title')
    const textareaIsNative = isHTMLTag('textarea')
    const titleNotVoid = !isVoidTag('title')
    const textareaNotVoid = !isVoidTag('textarea')
    const titleNotCore = !isCoreComponent('title')
    const textareaNotCore = !isCoreComponent('textarea')
    let reconstructedIsHtml = false
    let reconstructedNotVoid = true
    let reconstructedNotCore = true
    if (rcdataTagName !== '') {
      reconstructedIsHtml = isHTMLTag(rcdataTagName)
      reconstructedNotVoid = !isVoidTag(rcdataTagName)
      reconstructedNotCore = !isCoreComponent(rcdataTagName)
    }

    const interpolatableBySequence =
      isTitleSequence || (isTextareaSequence && !inSfcRoot)
    const interpolatableByTag = [
      titleIsNative,
      textareaIsNative,
      titleNotVoid,
      textareaNotVoid,
      titleNotCore,
      textareaNotCore,
      reconstructedIsHtml || interpolatableBySequence,
      reconstructedNotVoid,
      reconstructedNotCore,
    ].every(Boolean)
    const treatAsInterpolatableRCDATA =
      interpolatableBySequence && interpolatableByTag

    const isWhitespaceChar = isWhitespace(c)
    const currentSequenceIndex = this.sequenceIndex
    const currentSectionStart = this.sectionStart
    const currentBufferIndex = this.index
    const currentBufferLength = this.buffer.length

    if (currentSequenceIndex === sequenceLength) {
      if (c === CharCodes.Gt || isWhitespaceChar) {
        const endOfText = currentBufferIndex - sequenceLength
        const hasPendingText = currentSectionStart < endOfText
        if (hasPendingText) {
          // Spoof the index so that reported locations match up.
          const actualIndex = this.index
          const textStart = currentSectionStart
          const textEnd = endOfText
          this.index = textEnd
          this.cbs.ontext(textStart, textEnd)
          this.index = actualIndex
        }

        const closingNameStart = endOfText + 2 // Skip over the `</`
        this.sectionStart = closingNameStart
        const closingNameEnd = this.index
        this.cbs.onclosetag(closingNameStart, closingNameEnd)
        this.sectionStart = -1
        this.state = State.AfterClosingTagName
        if (c === CharCodes.Gt) {
          const afterTagIndex = this.index + 1
          this.state = State.Text
          this.sectionStart = afterTagIndex
        }
        this.inRCDATA = false
        return // We are done; skip the rest of the function.
      }

      this.sequenceIndex = 0
    }

    const expected = sequence[this.sequenceIndex]
    const folded = c | 0x20
    if (folded === expected) {
      this.sequenceIndex = this.sequenceIndex + 1
    } else if (this.sequenceIndex === 0) {
      if (treatAsInterpolatableRCDATA) {
        // We have to parse entities in <title> and <textarea> tags.
        if (!__BROWSER__ && c === CharCodes.Amp) {
          this.startEntity()
        } else if (c === this.delimiterOpen[0]) {
          // We also need to handle interpolation
          this.state = State.InterpolationOpen
          this.delimiterIndex = 0
          const delimiterIndex = this.delimiterIndex
          const delimiterCode = delimiterOpen[delimiterIndex]
          if (c === delimiterCode) {
            const isLastDelimiterChar =
              delimiterIndex === delimiterOpenLength - 1
            if (isLastDelimiterChar) {
              const interpolationStart =
                this.index + 1 - delimiterOpenLength
              if (interpolationStart > this.sectionStart) {
                const leadingTextStart = this.sectionStart
                const leadingTextEnd = interpolationStart
                this.cbs.ontext(leadingTextStart, leadingTextEnd)
              }
              this.state = State.Interpolation
              this.sectionStart = interpolationStart
            } else {
              this.delimiterIndex = delimiterIndex + 1
            }
          }
        }
      } else {
        let foundLt = false
        let scanIndex = this.index
        const searchChar = CharCodes.Lt
        const bufferLength = currentBufferLength
        while (++scanIndex < bufferLength) {
          const cc = this.buffer.charCodeAt(scanIndex)
          if (cc === CharCodes.NewLine) {
            this.newlines.push(scanIndex)
          }
          if (cc === searchChar) {
            foundLt = true
            this.index = scanIndex
            break
          }
        }
        if (!foundLt) {
          this.index = bufferLength - 1
        } else {
          this.sequenceIndex = 1
        }
      }
    } else {
      // If we see a `<`, set the sequence index to 1; useful for eg. `<</script>`.
      this.sequenceIndex = Number(c === CharCodes.Lt)
    }

